        row.MouseLeave:Connect(function() TS:Create(stroke, TweenInfo.new(0.12), {Transparency = row:GetAttribute("MVPActive") and ROWHOV_ON or ROWHOV_OFF}):Play() end)
        return row
    end
    local function mkLabel(row, text)
        local l = MVPUI.text(row, string.upper(tostring(text)), UDim2.fromOffset(16, 0), UDim2.new(0.48, -8, 1, 0), 11, WHITE, 8)
        l.Font = Enum.Font.GothamBold
        l.Name = "RowLabel"
        l.TextWrapped = true   -- teks panjang turun ke baris ke-2, tidak terpotong
        local c = l:FindFirstChildOfClass("UITextSizeConstraint")
        if c then c.MinTextSize = 9 end
        return l
    end
    -- lebar label disesuaikan dengan kontrol di sisi kanan baris (kotak / selector / tombol / toggle)
    local function sizeRowLabel(row, controlW)
        local l = row and row:FindFirstChild("RowLabel")
        if l then l.Size = UDim2.new(1, -(16 + controlW + 8), 1, 0) end
    end
    -- Toggle circular (sin interruptor alargado): gris fuerte apagado y blanco activo.
    local function mkCircleToggle(row)
        local circle = MVPUI.new("Frame", row, {Name = "CircleToggle", Size = UDim2.fromOffset(24, 24),
            AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -18, 0.5, 0),
            BackgroundColor3 = Color3.fromRGB(75, 75, 75), BorderSizePixel = 0, ZIndex = 8})
        MVPUI.round(circle, 12)
        local stroke = MVPUI.stroke(circle, Color3.fromRGB(0, 0, 0), 0, 1.5)
        return circle, stroke
    end
    local function animCircle(circle, on)
        TS:Create(circle, TweenInfo.new(0.14), {BackgroundColor3 = on and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(75, 75, 75)}):Play()
        local stroke = circle:FindFirstChildOfClass("UIStroke")
        if stroke then stroke.Color = Color3.fromRGB(0, 0, 0); stroke.Transparency = 0 end
    end
    local function mkToggle(page, text, callback)
        local row = mkRow(page, 46)
        local label = mkLabel(row, text)
        sizeRowLabel(row, 70)
        local circle = mkCircleToggle(row)
        local on = false
        local function set(value)
            on = value == true
            row:SetAttribute("MVPActive", on)
            animCircle(circle, on)
            if label and label:IsA("TextLabel") then
                label.TextColor3 = on and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(75, 75, 75)
                label.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
                label.TextStrokeTransparency = 0
            end
            local rowStroke = row:FindFirstChildOfClass("UIStroke")
            if rowStroke then rowStroke.Color = Color3.fromRGB(0, 0, 0); rowStroke.Transparency = 0 end
        end
        local hit = MVPUI.new("TextButton", row, {Name = "ToggleHit", Size = UDim2.fromScale(1, 1), Text = "",
            BackgroundTransparency = 1, AutoButtonColor = false, ZIndex = 10})
        hit.Activated:Connect(function()
            local previous = on
            set(not on)
            local ok, err = pcall(callback, on)
            if not ok then set(previous); warn("[ZYROX DUELS] " .. text .. ": " .. tostring(err)) end
            task.defer(function() pcall(saveAllSettings) end)
        end)
        return set
    end
    local function mkSelector(row, default, options, callback)
